-- Run 5.1 (P-86, D-40). Generated by drizzle-kit, the REVOKE added by hand.
--
-- A machine credential is issuing -> active -> revoking -> revoked, or
-- issuing -> needs_review, or active -> expired. The partial unique index is
-- the rule "an unresolved issuance blocks new issuance for that environment".
-- The API keeps UPDATE on accessor, effective_expires_at, state and
-- last_used_at only: name, issuance operation, requested expiry and issuer are
-- written at insert and never changed.
CREATE UNIQUE INDEX "machine_credential_unresolved_issuance_key" ON "app"."machine_credential" USING btree ("environment_id") WHERE "app"."machine_credential"."state" IN ('issuing', 'needs_review');--> statement-breakpoint
CREATE INDEX "machine_credential_environment_state_idx" ON "app"."machine_credential" USING btree ("environment_id","state");--> statement-breakpoint
REVOKE UPDATE (name, issuance_operation_id, requested_expires_at, issued_by) ON app.machine_credential FROM api_runtime;
